{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "a3lem-claude-plugins",
  "owner": {
    "name": "Adriaan",
    "email": "a3lem@pm.me"
  },
  "metadata": {"description": "Personal collection of Claude Code plugins"},
  "plugins": [
    {
      "name": "spec-driven-dev",
      "source": "./plugins/spec-driven-dev",
      "description": "Spec-driven development with structured directories, borrowing ideas from Kiro and Spec-kit"
    },
    {
      "name": "basedpyright-lsp",
      "source": "./plugins/basedpyright-lsp",
      "description": "Enable basedpyright LSP server for Python"
    },
    {
      "name": "python-rules",
      "source": "./plugins/python-rules",
      "description": "Python coding preferences and conventions -- how I like to write Python"
    },
    {
      "name": "theo-calvin-testing",
      "source": "./plugins/theo-calvin-testing",
      "description": "Differential testing with tc - input.json to output.json, diffed against expected.json"
    },
    {
      "name": "session-setup",
      "source": "./plugins/session-setup",
      "description": "Automatically prompt execution of Session Setup steps from CLAUDE.md on session start"
    },
    {
      "name": "ticket-cli",
      "source": "./plugins/ticket-cli",
      "description": "Integration for the tk CLI ticket system - git-backed issue tracking for AI agents"
    },
    {
      "name": "auto-memory",
      "source": "./plugins/auto-memory",
      "description": "Persistent auto-memory across sessions with configurable storage location"
    },
    {
      "name": "frontmatter",
      "source": "./plugins/frontmatter",
      "description": "Manage AI provenance metadata blocks in source files to track review status, rule references, and access control"
    },
    {
      "name": "better-comments",
      "source": "./plugins/better-comments",
      "description": "Structured [AI] comment blocks with provenance, context, intent, and assumptions for meaningful code review"
    },
    {
      "name": "project-notes",
      "source": "./plugins/project-notes",
      "description": "Project knowledge management with notes, decision logs, and timestamped journal entries"
    },
    {
      "name": "project-knowledge",
      "source": "./plugins/project-knowledge",
      "description": "Routes knowledge to the right store: specs, notes, decisions, journal, or docs"
    }
  ]
}
